"""Sqrt(x) — binary search on the answer.

Look for the largest m with m*m <= x.

Time: O(log x)   Space: O(1)
"""


class Solution:
    def mySqrt(self, x: int) -> int:
        lo, hi, best = 0, x, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if mid * mid <= x:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best
